import java.math.BigDecimal
import java.math.RoundingMode

class Ledger {
    private val balances = HashMap<String, BigDecimal>()
    private val log = HashMap<String, MutableList<BigDecimal>>()

    fun openAccount(id: String, initial: BigDecimal = BigDecimal.ZERO) {
        if (balances.containsKey(id)) {
            throw IllegalArgumentException("account already exists")
        }
        require(initial.signum() >= 0) { "initial balance must be non-negative" }
        val normalized = normalize(initial)
        balances[id] = normalized
        log[id] = mutableListOf()
    }

    fun balance(id: String): BigDecimal {
        val b = balances[id] ?: throw NoSuchElementException("unknown account")
        return b.setScale(2, RoundingMode.UNNECESSARY)
    }

    fun transfer(from: String, to: String, amount: BigDecimal) {
        require(amount.signum() > 0) { "amount must be positive" }
        val normalized = normalize(amount)
        val fromBalance = balances[from] ?: throw NoSuchElementException("unknown account")
        val toBalance = balances[to] ?: throw NoSuchElementException("unknown account")
        if (fromBalance < normalized) {
            throw IllegalStateException("insufficient funds")
        }
        balances[from] = fromBalance.subtract(normalized)
        log.getValue(from).add(normalized.negate())
        balances[to] = toBalance.add(normalized)
        log.getValue(to).add(normalized)
    }

    fun history(id: String): List<BigDecimal> {
        val entries = log[id] ?: throw NoSuchElementException("unknown account")
        return entries.map { it.setScale(2, RoundingMode.UNNECESSARY) }
    }

    companion object {
        fun split(total: BigDecimal, n: Int): List<BigDecimal> {
            require(n > 0) { "n must be positive" }
            require(total.signum() >= 0) { "total must be non-negative" }
            val normalizedTotal = normalize(total)
            // Convert to cents for exact integer arithmetic
            val totalCents = normalizedTotal.movePointRight(2).toLong()
            val baseCents = totalCents / n
            val remainder = (totalCents % n).toInt()
            val base = BigDecimal(baseCents).movePointLeft(2)
            val larger = base.add(BigDecimal.ONE.movePointLeft(2))
            return List(n) { i -> if (i < remainder) larger else base }
        }

        private fun normalize(amount: BigDecimal): BigDecimal {
            // Reject amounts with more than 2 decimal places
            if (amount.scale() > 2 && amount.stripTrailingZeros().scale() > 2) {
                throw IllegalArgumentException("amount must have at most 2 decimal places")
            }
            return amount.setScale(2, RoundingMode.UNNECESSARY)
        }
    }
}
