class LruCache<K, V>(val capacity: Int, private val onEvict: (K, V) -> Unit = { _, _ -> }) {
    init {
        require(capacity >= 1) { "capacity must be >= 1" }
    }

    private val entries = LinkedHashMap<K, V>()
    private var sizeCounter: Int = 0

    val size: Int get() = sizeCounter

    operator fun get(key: K): V? {
        if (!entries.containsKey(key)) return null
        // Mark as most recently used by removing and re-inserting
        val value = entries.remove(key)!!
        entries[key] = value
        return value
    }

    operator fun set(key: K, value: V) {
        if (entries.containsKey(key)) {
            // Update existing key - mark as most recently used
            entries.remove(key)
            entries[key] = value
        } else {
            // Insert new key
            entries[key] = value
            sizeCounter++
            if (sizeCounter > capacity) {
                // Evict least recently used (first entry in LinkedHashMap)
                val firstKey = entries.keys.first()
                val evictedValue = entries.remove(firstKey)!!
                onEvict(firstKey, evictedValue)
                sizeCounter--
            }
        }
    }

    fun remove(key: K): V? {
        if (!entries.containsKey(key)) return null
        val value = entries.remove(key)!!
        sizeCounter--
        return value
    }

    fun keys(): List<K> {
        return entries.keys.toList()
    }

    operator fun contains(key: K): Boolean {
        return entries.containsKey(key)
    }
}
