sealed class Token {
    abstract val pos: Int  // 0-based index of the token's first character
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}

class TokenizeException(message: String, val pos: Int) : Exception(message)

fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    val n = input.length

    while (i < n) {
        val c = input[i]

        // Skip whitespace
        if (c == ' ' || c == '\t' || c == '\n') {
            i++
            continue
        }

        // Parentheses
        if (c == '(') {
            tokens.add(Token.Paren(true, i))
            i++
            continue
        }
        if (c == ')') {
            tokens.add(Token.Paren(false, i))
            i++
            continue
        }

        // Strings
        if (c == '"' || c == '\'') {
            val startPos = i
            val quote = c
            i++
            val sb = StringBuilder()
            var terminated = false
            while (i < n) {
                val ch = input[i]
                if (ch == '\\') {
                    if (i + 1 >= n) {
                        throw TokenizeException("Unterminated string", startPos)
                    }
                    i++
                    val escaped = input[i]
                    when (escaped) {
                        'n' -> sb.append('\n')
                        else -> sb.append(escaped)
                    }
                    i++
                } else if (ch == quote) {
                    terminated = true
                    i++
                    break
                } else {
                    sb.append(ch)
                    i++
                }
            }
            if (!terminated) {
                throw TokenizeException("Unterminated string", startPos)
            }
            tokens.add(Token.Str(sb.toString(), startPos))
            continue
        }

        // Numbers and minus sign
        if (c == '-' || c in '0'..'9') {
            val startPos = i
            var numStart = i

            // Check if it's a negative number
            if (c == '-') {
                // A leading '-' is only valid when the previous token is absent, an Op, or an opening paren
                if (tokens.isNotEmpty()) {
                    val lastToken = tokens.last()
                    if (lastToken !is Token.Op && !(lastToken is Token.Paren && lastToken.open)) {
                        throw TokenizeException("Unexpected '-' character", i)
                    }
                }
                numStart = i + 1
                if (numStart >= n || input[numStart] !in '0'..'9') {
                    throw TokenizeException("Invalid number: expected digit after '-'", i)
                }
            }

            // Parse digits
            var j = numStart
            while (j < n && input[j] in '0'..'9') {
                j++
            }

            // Check for fraction part
            if (j < n && input[j] == '.') {
                j++
                if (j >= n || input[j] !in '0'..'9') {
                    throw TokenizeException("Invalid number: expected digit after '.'", startPos)
                }
                while (j < n && input[j] in '0'..'9') {
                    j++
                }
            }

            // Check that we didn't have a trailing dot without digits (e.g., "5.")
            // Also check that the number isn't immediately followed by more digits or a dot that would make it invalid
            // Actually, let's verify: if the original char was just '-' and no digit followed, error.
            // The parsing above handles this: if numStart >= n or not a digit, we throw.

            val numStr = input.substring(startPos, j)
            try {
                val value = numStr.toDouble()
                tokens.add(Token.Num(value, startPos))
            } catch (e: NumberFormatException) {
                throw TokenizeException("Invalid number: $numStr", startPos)
            }
            i = j
            continue
        }

        // Identifiers
        if (c in 'A'..'Z' || c in 'a'..'z' || c == '_') {
            val startPos = i
            var j = i + 1
            while (j < n && (input[j] in 'A'..'Z' || input[j] in 'a'..'z' || input[j] in '0'..'9' || input[j] == '.')) {
                j++
            }
            val name = input.substring(startPos, j)
            tokens.add(Token.Ident(name, startPos))
            i = j
            continue
        }

        // Operators (longest match first)
        if (i + 1 < n) {
            val twoChar = input.substring(i, i + 2)
            if (twoChar == "==" || twoChar == "!=" || twoChar == "<=" || twoChar == ">=" || twoChar == "&&" || twoChar == "||") {
                tokens.add(Token.Op(twoChar, i))
                i += 2
                continue
            }
        }

        if (c == '=' && i + 1 < n && input[i + 1] == '=') {
            // Already handled above
        }

        if (c in "!=<>!&|" && c != '=' && c != '!' || c == '<' || c == '>') {
            // Single character operators: !, <, >
            // But we need to be careful: ! is a single char op, but != is two chars.
            // We already checked two-char matches above.
            if (c == '!' || c == '<' || c == '>') {
                tokens.add(Token.Op(c.toString(), i))
                i++
                continue
            }
        }

        throw TokenizeException("Unexpected character: '$c'", i)
    }

    return tokens
}
