import copy


def merge(base: dict, *overrides: dict) -> dict:
    """Deep merge configuration layers where later overrides win.

    - Dicts are merged recursively.
    - Any other value in an override replaces the base value (lists replaced).
    - A key whose override value is None deletes that key from the result.
    - A key ending in '+' appends: {"plugins+": ["x"]} appends items to base list "plugins".
      If base value exists and is not a list, raise TypeError.
      The '+' key itself never appears in the result.
    - Inputs are not mutated; result does not share mutable dicts/lists with inputs (deep copy).
    """

    def _deep_copy(value):
        """Create a deep copy of a value."""
        if isinstance(value, dict):
            return {k: _deep_copy(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_deep_copy(item) for item in value]
        else:
            return copy.deepcopy(value)

    def _merge_into(target: dict, override: dict):
        """Merge override into target (both are already deep copies)."""
        for key, value in override.items():
            if key.endswith('+'):
                # Handle append operation
                base_key = key[:-1]
                if not isinstance(value, list):
                    raise TypeError(f"Value for '+' key '{key}' must be a list")

                if base_key in target:
                    existing = target[base_key]
                    if not isinstance(existing, list):
                        raise TypeError(
                            f"Cannot append to non-list value for key '{base_key}'"
                        )
                    # Append deep copies of the new items
                    for item in value:
                        existing.append(_deep_copy(item))
                else:
                    # Base doesn't exist, create new list with deep copies
                    target[base_key] = _deep_copy(value)
            elif value is None:
                # Delete key if it exists
                if key in target:
                    del target[key]
            elif isinstance(value, dict):
                if key in target and isinstance(target[key], dict):
                    # Recursively merge dicts
                    _merge_into(target[key], value)
                else:
                    # Replace with deep copy of the override dict
                    target[key] = _deep_copy(value)
            else:
                # Replace with deep copy of the value
                target[key] = _deep_copy(value)

    # Start with a deep copy of base
    result = _deep_copy(base)

    # Apply each override in order
    for override in overrides:
        if not isinstance(override, dict):
            raise TypeError(f"Expected dict, got {type(override).__name__}")
        _merge_into(result, override)

    return result
