def parse_duration(s: str) -> int:
    if not s or not isinstance(s, str):
        raise ValueError("Empty or invalid input")

    # Strip leading/trailing whitespace
    s = s.strip()
    if not s:
        raise ValueError("Empty input")

    units_order = ['d', 'h', 'm', 's']
    unit_values = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}

    i = 0
    n = len(s)
    total_seconds = 0
    last_unit_index = -1

    while i < n:
        # Skip single space (optional separator between parts)
        if s[i] == ' ':
            i += 1
            continue

        # Parse integer
        start = i
        while i < n and s[i].isdigit():
            i += 1
        if i == start:
            raise ValueError(f"Missing number at position {start}")

        num_str = s[start:i]
        value = int(num_str)

        # Parse unit
        if i >= n:
            raise ValueError("Missing unit after number")

        unit_char = s[i].lower()
        if unit_char not in unit_values:
            raise ValueError(f"Unknown unit '{s[i]}'")

        current_unit_index = units_order.index(unit_char)
        if current_unit_index <= last_unit_index:
            raise ValueError("Units out of order or repeated")
        last_unit_index = current_unit_index

        total_seconds += value * unit_values[unit_char]
        i += 1

    # Check that we consumed the entire string (no trailing invalid chars)
    if i != n:
        raise ValueError(f"Invalid character at position {i}")

    # Verify there was at least one part
    if last_unit_index == -1:
        raise ValueError("No valid parts found")

    return total_seconds


def format_duration(seconds: int) -> str:
    if not isinstance(seconds, int):
        raise ValueError("Input must be an integer")
    if seconds < 0:
        raise ValueError("Negative input is not allowed")

    if seconds == 0:
        return "0s"

    units = [
        ('d', 86400),
        ('h', 3600),
        ('m', 60),
        ('s', 1)
    ]

    parts = []
    remaining = seconds

    for unit_name, unit_seconds in units:
        if remaining >= unit_seconds:
            count = remaining // unit_seconds
            remaining -= count * unit_seconds
            if count > 0:
                parts.append(f"{count}{unit_name}")

    return ''.join(parts)
