def flatten(obj, sep="."):
    """Flatten a nested dict/list structure into a flat dict with path keys."""
    if not isinstance(obj, dict):
        raise TypeError("top-level object must be a dict")

    result = {}

    def _flatten(value, prefix):
        if isinstance(value, dict):
            if len(value) == 0:
                # Empty dict is a leaf value
                result[prefix] = value
            else:
                for key, val in value.items():
                    if not isinstance(key, str):
                        raise ValueError("keys must be strings")
                    if sep in key:
                        raise ValueError(f"key {key!r} contains separator {sep!r}")
                    new_prefix = f"{prefix}{sep}{key}" if prefix else key
                    _flatten(val, new_prefix)
        elif isinstance(value, list):
            if len(value) == 0:
                # Empty list is a leaf value
                result[prefix] = value
            else:
                for i, val in enumerate(value):
                    new_prefix = f"{prefix}{sep}{i}"
                    _flatten(val, new_prefix)
        else:
            # Leaf value
            result[prefix] = value

    _flatten(obj, "")
    return result


def unflatten(flat, sep="."):
