        # Check if this segment is a list index
        is_list_index = (
            current.isdigit() and 
            (current == "0" or not current.startswith("0"))
        )

        if idx == len(segments) - 1:
            # Leaf node
            return None, value_at_leaf(segments)

        # Internal node - need to determine if dict or list
        # Look at all paths that share this prefix
