            if len(segs) > idx and _prefix_matches(segs, remaining_segments[:idx+1], idx):
                child_keys.add(segs[idx])

        # Actually, let's use a different approach - build recursively
        pass

    # Better approach: build the tree structure first
    # Create a tree of nodes
    root = {}  # We'll use a special marker for lists vs dicts

    class Node:
        def __init__(self):
            self.children = {}  # key -> Node or value
            self.is_list = False
            self.list_children = []
            self.value = None
            self.has_value = False
            self.is_leaf = False

    root_node = Node()

    for key, (segments, value) in paths.items():
        node = root_node
