            if is_last:
                # Leaf
                if node.has_value or not node.is_leaf and (node.children or node.list_children):
                    raise ValueError(f"conflicting paths at {key!r}")
                node.value = value
                node.has_value = True
                node.is_leaf = True
            else:
                # Internal node - need to descend
                is_list_index = (
                    seg.isdigit() and 
                    (seg == "0" or not seg.startswith("0"))
                )

                if is_list_index:
                    idx = int(seg)
                    if not node.is_list:
                        node.is_list = True
                    if idx >= len(node.list_children):
                        # Extend list with None placeholders
                        while len(node.list_children) <= idx:
                            node.list_children.append(None)
                    if node.list_children[idx] is None:
                        node.list_children[idx] = Node()
                    node = node.list_children[idx]
                else:
                    if node.is_list:
                        raise ValueError(f"conflict: list and dict mixed at {key!r}")
                    if seg not in node.children:
                        node.children[seg] = Node()
                    node = node.children[seg]

    def _convert(node):
        """Convert a Node tree back to Python objects."""
        if node is None:
            raise ValueError("invalid structure")

        if node.is_leaf and node.has_value:
            return node.value

        if node.is_list:
            # Ensure dense list
            max_idx = len(node.list_children) - 1
            for i in range(max_idx + 1):
                if node.list_children[i] is None:
                    raise ValueError(f"list must be dense, missing index {i}")
            return [_convert(child) for child in node.list_children]
        else:
            result = {}
            for key, child in node.children.items():
                result[key] = _convert(child)
            return result

    return _convert(root_node)
