def flatten(obj, sep="."):
    """Flatten a nested dict/list structure into a flat dict with path keys."""
    if not isinstance(obj, dict):
        raise TypeError("top-level object must be a dict")

    result = {}

    def _flatten(value, prefix):
        if isinstance(value, dict):
            if len(value) == 0:
                # Empty dict is a leaf value
                result[prefix] = value
            else:
                for key, val in value.items():
                    if not isinstance(key, str):
                        raise ValueError("keys must be strings")
                    if sep in key:
                        raise ValueError(f"key {key!r} contains separator {sep!r}")
                    new_prefix = f"{prefix}{sep}{key}" if prefix else key
                    _flatten(val, new_prefix)
        elif isinstance(value, list):
            if len(value) == 0:
                # Empty list is a leaf value
                result[prefix] = value
            else:
                for i, val in enumerate(value):
                    new_prefix = f"{prefix}{sep}{i}"
                    _flatten(val, new_prefix)
        else:
            # Leaf value
            result[prefix] = value

    _flatten(obj, "")
    return result


def unflatten(flat, sep="."):
    """Unflatten a flat dict with path keys back into nested dicts/lists."""
    if not isinstance(flat, dict):
        raise TypeError("input must be a dict")

    # Handle empty input
    if len(flat) == 0:
        return {}

    # Check for empty key
    if "" in flat:
        if len(flat) != 1:
            raise ValueError("conflicting paths with empty key")
        return flat[""]

    # Parse all keys into segments
    entries = []
    for key, value in flat.items():
        if not isinstance(key, str):
            raise ValueError("keys must be strings")
        segments = key.split(sep)
        entries.append((segments, value))

    # Build a tree structure
    # Each node can be:
    # - A leaf (has a value)
    # - A dict (has string-keyed children)
    # - A list (has integer-indexed children)

    class Node:
        def __init__(self):
            self.value = None
            self.is_leaf = False
            self.children = {}  # for dicts: str -> Node
            self.list_children = []  # for lists: index -> Node

    root = Node()

    for segments, value in entries:
        node = root
        for i, seg in enumerate(segments):
            is_last = (i == len(segments) - 1)

            if is_last:
                # This is a leaf
                if node.is_leaf:
                    raise ValueError(f"conflicting paths")
                if node.children or node.list_children:
                    raise ValueError(f"conflicting paths")
                node.value = value
                node.is_leaf = True
            else:
                # Need to descend into this segment
                is_list_index = (
                    seg.isdigit() and 
                    (seg == "0" or not seg.startswith("0"))
                )

                if is_list_index:
                    idx = int(seg)
                    if node.is_leaf:
                        raise ValueError(f"conflicting paths")
                    # If node already has dict children, conflict
                    if node.children:
                        raise ValueError(f"conflicting paths: list and dict mixed")
                    if not node.list_children:
                        pass  # will extend below
                    while len(node.list_children) <= idx:
                        node.list_children.append(None)
                    if node.list_children[idx] is None:
                        node.list_children[idx] = Node()
                    node = node.list_children[idx]
                else:
                    if node.is_leaf:
                        raise ValueError(f"conflicting paths")
                    # If node already has list children, conflict
                    if node.list_children:
                        raise ValueError(f"conflicting paths: dict and list mixed")
                    if seg not in node.children:
                        node.children[seg] = Node()
                    node = node.children[seg]

    def _convert(node):
        """Convert a Node tree back to Python objects."""
        if node is None:
            raise ValueError("invalid structure")

        if node.is_leaf:
            return node.value

        # Check if it's a list or dict
        has_list_children = len(node.list_children) > 0
        has_dict_children = len(node.children) > 0

        if has_list_children and has_dict_children:
            raise ValueError("conflicting paths: list and dict mixed")

        if has_list_children:
            # Ensure dense list - all indices from 0 to max must be present
            for i, child in enumerate(node.list_children):
                if child is None:
                    raise ValueError(f"list must be dense, missing index {i}")
            return [_convert(child) for child in node.list_children]
        elif has_dict_children:
            result = {}
            for key, child in node.children.items():
                result[key] = _convert(child)
            return result
        else:
            # Empty container - but this shouldn't happen from unflatten
            # unless the input had no entries for this path
            raise ValueError("invalid structure: empty internal node")

    return _convert(root)
