def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    if env is None:
        env = {}

    # Token types
    class TokenType:
        INT = 'INT'
        FLOAT = 'FLOAT'
        IDENT = 'IDENT'
        PLUS = '+'
        MINUS = '-'
        STAR = '*'
        SLASH = '/'
        PERCENT = '%'
        CARET = '^'
        LPAREN = '('
        RPAREN = ')'
        COMMA = ','
        COLON = ':'
        QMARK = '?'
        EQ = '=='
        NEQ = '!='
        LT = '<'
        LE = '<='
        GT = '>'
        GE = '>='
        ANDAND = '&&'
        OROR = '||'
        BANG = '!'
        EOF = 'EOF'

    class Token:
        def __init__(self, type_: str, value=None):
            self.type = type_
            self.value = value

        def __repr__(self):
            return f"Token({self.type}, {self.value!r})"

    def tokenize(s: str) -> list[Token]:
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c.isspace():
                i += 1
            elif c.isdigit() or (c == '.' and i + 1 < n and s[i+1].isdigit()):
                # Number literal
                start = i
                has_dot = False
                while i < n:
                    if s[i].isdigit():
                        i += 1
                    elif s[i] == '.' and not has_dot:
                        has_dot = True
                        i += 1
                    else:
                        break
                num_str = s[start:i]
                if has_dot:
                    tokens.append(Token(TokenType.FLOAT, float(num_str)))
                else:
                    tokens.append(Token(TokenType.INT, int(num_str)))
            elif c.isalpha() or c == '_':
                start = i
                while i < n and (s[i].isalnum() or s[i] == '_'):
                    i += 1
                ident = s[start:i]
                tokens.append(Token(TokenType.IDENT, ident))
            elif c == '+':
                tokens.append(Token(TokenType.PLUS))
                i += 1
            elif c == '-':
                tokens.append(Token(TokenType.MINUS))
                i += 1
            elif c == '*':
                tokens.append(Token(TokenType.STAR))
                i += 1
            elif c == '/':
                tokens.append(Token(TokenType.SLASH))
                i += 1
            elif c == '%':
                tokens.append(Token(TokenType.PERCENT))
                i += 1
            elif c == '^':
                tokens.append(Token(TokenType.CARET))
                i += 1
            elif c == '(':
                tokens.append(Token(TokenType.LPAREN))
                i += 1
            elif c == ')':
                tokens.append(Token(TokenType.RPAREN))
                i += 1
            elif c == ',':
                tokens.append(Token(TokenType.COMMA))
                i += 1
            elif c == ':':
                tokens.append(Token(TokenType.COLON))
                i += 1
            elif c == '?':
                tokens.append(Token(TokenType.QMARK))
                i += 1
            elif c == '=':
                if i + 1 < n and s[i+1] == '=':
                    tokens.append(Token(TokenType.EQ))
                    i += 2
                else:
                    raise SyntaxError(f"Unexpected character '=' at position {i}")
            elif c == '!':
                if i + 1 < n and s[i+1] == '=':
                    tokens.append(Token(TokenType.NEQ))
                    i += 2
                else:
                    tokens.append(Token(TokenType.BANG))
                    i += 1
            elif c == '<':
                if i + 1 < n and s[i+1] == '=':
                    tokens.append(Token(TokenType.LE))
                    i += 2
                else:
                    tokens.append(Token(TokenType.LT))
                    i += 1
            elif c == '>':
                if i + 1 < n and s[i+1] == '=':
                    tokens.append(Token(TokenType.GE))
                    i += 2
                else:
                    tokens.append(Token(TokenType.GT))
                    i += 1
            elif c == '&':
                if i + 1 < n and s[i+1] == '&':
                    tokens.append(Token(TokenType.ANDAND))
                    i += 2
                else:
                    raise SyntaxError(f"Unexpected character '&' at position {i}")
            elif c == '|':
                if i + 1 < n and s[i+1] == '|':
                    tokens.append(Token(TokenType.OROR))
                    i += 2
                else:
                    raise SyntaxError(f"Unexpected character '|' at position {i}")
            else:
                raise SyntaxError(f"Unexpected character '{c}' at position {i}")

        tokens.append(Token(TokenType.EOF))
        return tokens

    class Parser:
        def __init__(self, tokens: list[Token], env: dict[str, float]):
            self.tokens = tokens
            self.pos = 0
            self.env = env

        def peek(self) -> Token:
            return self.tokens[self.pos]

        def advance(self) -> Token:
            tok = self.tokens[self.pos]
            self.pos += 1
            return tok

        def expect(self, type_: str) -> Token:
            tok = self.peek()
            if tok.type != type_:
                raise SyntaxError(f"Expected {type_} but got {tok.type}")
            return self.advance()

        def parse(self) -> int | float:
            if self.peek().type == TokenType.EOF:
                raise SyntaxError("Empty input")
            result = self.parse_conditional()
            if self.peek().type != TokenType.EOF:
                raise SyntaxError(f"Trailing tokens: {self.peek()}")
            return result

        def parse_conditional(self) -> int | float:
            # a ? b : c, right-associative
            cond = self.parse_or()
            if self.peek().type == TokenType.QMARK:
                self.advance()  # consume '?'
