            sections[current_section] = {}
        sections[current_section][key_part] = value_str

        i = next_i

    # Remove empty default section if it has no keys
    if "" in sections and len(sections[""]) == 0:
        del sections[""]

    # Second pass: interpolation
    _interpolate(sections)

    return sections


