    """Find the first unquoted = or : in the line."""
    in_quotes = False
    escape_next = False

    for j, ch in enumerate(line):
        if escape_next:
            escape_next = False
            continue
        if ch == '\\' and in_quotes:
            escape_next = True
            continue
        if ch == '"':
            in_quotes = not in_quotes
            continue
        if not in_quotes:
            if ch == '=' or ch == ':':
                return j

    return -1


def _parse_value_with_continuation(value_part: str, start_line_idx: int, lines: list[str], n: int) -> tuple[str, int]:
    """Parse the value part, handling inline comments, quotes, and continuation lines."""
    # First, process the initial value line
    value_str = _process_value_line(value_part.strip(), start_line_idx + 1)

    # Check for continuation lines
    j = start_line_idx + 1
    while j < n:
        next_line = lines[j]

        if next_line.strip() == '':
            break

        if next_line[0] in (' ', '\t'):
            # Continuation line
            cont_value = _process_value_line(next_line.strip(), j + 1)
            value_str += '\n' + cont_value
            j += 1
        else:
            break

    return value_str, j


def _process_value_line(value_part: str, line_num: int) -> str:
    """Process a single value line (or continuation line), handling inline comments and quotes."""
    # First check if the value is fully quoted
    stripped = value_part.strip()

    if stripped.startswith('"'):
        # Try to parse as a fully quoted string
        result, remaining, found_close = _parse_quoted(stripped, line_num)

        if not found_close:
            raise ValueError(f"line {line_num}: unterminated quote")

        # Check that remaining is only whitespace or comment
        rem_stripped = remaining.strip()
        if rem_stripped and not (rem_stripped.startswith('#') or rem_stripped.startswith(';')):
            # There's extra content - this shouldn't happen for valid input, but handle gracefully
            pass

        return result

    # Not quoted - process inline comments
    return _remove_inline_comments(stripped)


def _parse_quoted(s: str, line_num: int) -> tuple[str, str, bool]:
    """Parse a quoted string starting at s[0]. Returns (content, remaining, found_close)."""
    if not s.startswith('"'):
        return "", s, False

    result = []
    k = 1
    escape_next = False
    found_close = False

    while k < len(s):
        ch = s[k]
        if escape_next:
            if ch == '"':
                result.append('"')
            elif ch == '\\':
                result.append('\\')
            else:
                result.append('\\')
                result.append(ch)
            escape_next = False
            k += 1
            continue
        if ch == '\\':
            escape_next = True
            k += 1
            continue
        if ch == '"':
            found_close = True
            k += 1
            break
        result.append(ch)
        k += 1

    return ''.join(result), s[k:], found_close


def _remove_inline_comments(value: str) -> str:
    """Remove inline comments ( ; or # preceded by whitespace, unless in quotes)."""
    in_quotes = False
    escape_next = False

    for j, ch in enumerate(value):
        if escape_next:
            escape_next = False
            continue
        if ch == '\\' and in_quotes:
            escape_next = True
            continue
        if ch == '"':
            in_quotes = not in_quotes
            continue
        if not in_quotes:
            if ch in (';', '#') and j > 0 and value[j - 1] in (' ', '\t'):
                return value[:j].rstrip()

    return value.rstrip()


def _interpolate(sections: dict[str, dict[str, str]]) -> None:
    """Resolve ${key} and ${section:key} references recursively."""

    def resolve(section: str, key: str, visiting: set[tuple[str, str]]) -> str:
        if (section, key) in visiting:
            raise ValueError(f"cycle detected in interpolation for {section}:{key}")

        if section not in sections or key not in sections[section]:
            raise ValueError(f"undefined reference: {key} in section {section!r}")

        value = sections[section][key]

        # Resolve references in this value
        result = []
        i = 0
        while i < len(value):
            ch = value[i]
            if ch == '$' and i + 1 < len(value):
                next_ch = value[i + 1]
                if next_ch == '$':
                    result.append('$')
                    i += 2
                    continue
                if next_ch == '{':
                    # Find the closing }
                    close_idx = value.find('}', i + 2)
                    if close_idx == -1:
                        raise ValueError(f"undefined reference: unclosed ${{")
                    ref = value[i + 2:close_idx]

                    if ':' in ref:
                        sec, k = ref.split(':', 1)
                        sec = sec.strip()
                        k = k.strip().lower()
                    else:
                        sec = section
                        k = ref.strip().lower()

                    visiting.add((section, key))
                    try:
                        resolved = resolve(sec, k, visiting)
                    finally:
                        visiting.discard((section, key))

                    result.append(resolved)
                    i = close_idx + 1
                    continue
            result.append(ch)
            i += 1

        return ''.join(result)

    # Resolve all values
    for section in sections:
        for key in list(sections[section].keys()):
            sections[section][key] = resolve(section, key, set())
