    if v.is_prerelease:
        # Check if any comparator has a prerelease version with same major.minor.patch
        has_matching_prerelease = False
        for comp in comparators:
            if comp.version.is_prerelease:
                if (comp.version.major == v.major and
                    comp.version.minor == v.minor and
                    comp.version.patch == v.patch):
                    has_matching_prerelease = True
                    break

        if not has_matching_prerelease:
            return False

