        return self.prerelease is not None and len(self.prerelease) > 0

    def _compare_prerelease(self, other):
        """Compare prerelease parts. Returns -1, 0, or 1."""
        if not self.is_prerelease and not other.is_prerelease:
            return 0
        if not self.is_prerelease:
            return 1  # release > prerelease
        if not other.is_prerelease:
            return -1  # prerelease < release

        my_idents = self.prerelease
        their_idents = other.prerelease

        for i in range(max(len(my_idents), len(their_idents))):
            if i >= len(my_idents):
                return -1  # shorter is smaller
            if i >= len(their_idents):
                return 1  # longer is larger

            a = my_idents[i]
            b = their_idents[i]

            a_is_num = isinstance(a, int)
            b_is_num = isinstance(b, int)

            if a_is_num and b_is_num:
                if a < b:
                    return -1
                elif a > b:
                    return 1
                else:
