    # Regex for SemVer 2.0.0
    pattern = r'^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z\-\.]+))?(?:\+([0-9A-Za-z\-\.]+))?$'
    m = re.match(pattern, v)
    if not m:
        raise ValueError(f"Invalid version: {v}")

    major_str, minor_str, patch_str, prerelease_str, build_str = m.groups()

    # Check no leading zeros in numeric parts
    for part_name, part in [('major', major_str), ('minor', minor_str), ('patch', patch_str)]:
        if len(part) > 1 and part[0] == '0':
            raise ValueError(f"Leading zero in {part_name}: {v}")

    major = int(major_str)
    minor = int(minor_str)
    patch = int(patch_str)

    prerelease = None
    if prerelease_str:
        identifiers = prerelease_str.split('.')
        for ident in identifiers:
            if not ident:
                raise ValueError(f"Empty prerelease identifier in: {v}")
            # Check it's valid [0-9A-Za-z-]+
            if not re.match(r'^[0-9A-Za-z\-]+$', ident):
                raise ValueError(f"Invalid prerelease identifier '{ident}' in: {v}")
