        prerelease = []
        for ident in identifiers:
            if re.match(r'^\d+$', ident):
                # Purely numeric identifier - no leading zeros allowed
                if len(ident) > 1 and ident[0] == '0':
                    raise ValueError(f"Leading zero in numeric prerelease identifier: {v}")
                prerelease.append(int(ident))
            else:
                # Alphanumeric identifier (may start with digit but contains letters or hyphens)
                prerelease.append(ident)

