    def is_wildcard(s):
        return s is None or s in ('X', 'x', '*')

    has_major = not is_wildcard(major_s)
    has_minor = not is_wildcard(minor_s)
    has_patch = not is_wildcard(patch_s)

    major = 0 if is_wildcard(major_s) else int(major_s)
    minor = 0 if is_wildcard(minor_s) else int(minor_s)
    patch = 0 if is_wildcard(patch_s) else int(patch_s)

    # Validate no leading zeros in numeric parts
    for name, val in [('major', major_s), ('minor', minor_s), ('patch', patch_s)]:
        if not is_wildcard(val):
            v_str = str(val)
            if len(v_str) > 1 and v_str[0] == '0':
                raise ValueError(f"Leading zero in {name} of partial version: {s}")

