    """Check if annotation is Optional[T] (i.e., T | None)."""
    origin = typing.get_origin(annotation)
    args = typing.get_args(annotation)
    # Optional[T] is Union[T, NoneType]
    if origin is typing.Union or origin is getattr(typing, "Union", None):
