    if (length(buf) > 0) {
        print "Error: unterminated quote at end of input" > "/dev/stderr"
        exit 4
    }
    if (summode == 1 && header_done) {
        if (numcount == 0) {
            print "count=0"
        } else {
            printf "count=%d sum=%g min=%g max=%g\n", numcount, sum, min, max
        }
    }
}
